package com.order.menu.module.entertainment.mode.naval;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import com.order.menu.module.entertainment.mode.naval.NavalState.*;
import java.util.*;

class NavalMilitaryTest {
    @Test void sharedHullCapsAllowTwoFourSixAndKeepDecoysSeparate(){
        List<Ship> medium=new ArrayList<>();String[] types={"battleship","cruiser","submarine","cruiser","battleship"};for(int i=0;i<4;i++)medium.add(ship(types[i],"m"+i,-1,-1));assertEquals(145,NavalMilitary.validate(medium,false));medium.add(ship(types[4],"m4",-1,-1));assertThrows(RuntimeException.class,()->NavalMilitary.validate(medium,false));
        List<Ship> destroyers=new ArrayList<>();String[] kinds={"antiAir","radar","mineLayer","jammer","antiAir","radar"};for(int i=0;i<6;i++)destroyers.add(ship(kinds[i],"d"+i,-1,-1));assertEquals(150,NavalMilitary.validate(destroyers,false));for(int i=0;i<3;i++)destroyers.add(ship("decoy","decoy"+i,-1,-1));assertEquals(195,NavalMilitary.validate(destroyers,false));destroyers.add(ship("jammer","extra",-1,-1));assertThrows(RuntimeException.class,()->NavalMilitary.validate(destroyers,false));destroyers.remove(destroyers.size()-1);destroyers.add(ship("decoy","decoy3",-1,-1));assertThrows(RuntimeException.class,()->NavalMilitary.validate(destroyers,false));
    }
    @Test void locatedLiveHullKeepsItsInteriorAndExcludesOnlyItsRing(){
        Ship carrier=ship("carrier","live",4,2);carrier.hits.addAll(List.of("4,2","4,5"));NavalState s=battle(List.of(carrier),List.of(ship("cruiser","c",0,0)));s.players.get(0).shots.addAll(List.of(new Shot(4,2,"hit"),new Shot(4,5,"hit")));
        var k=new NavalMilitaryAi.Knowledge(s.players.get(1),s.players.get(0));assertFalse(k.intel.neutralized.contains("live"));assertEquals(1,k.intel.located.size());assertFalse(k.fresh(new Cell(5,3)));assertTrue(k.fresh(new Cell(4,3)));assertTrue(k.score(new Cell(4,3))>k.score(new Cell(8,8)));Action a=NavalMilitaryAi.choose(s);assertTrue(k.fresh(new Cell(a.x,a.y)));
    }
    @Test void radarNegativesAreOnlyRevisitedWhenOrdinaryDamageCandidatesExhaust(){
        NavalState s=battle(List.of(ship("cruiser","e",9,9)),List.of(ship("cruiser","c",0,0)));s.players.get(1).radar.add(new Radar(5,5,false));var k=new NavalMilitaryAi.Knowledge(s.players.get(1),s.players.get(0));assertEquals(0,k.score(new Cell(5,5)));assertTrue(k.score(new Cell(5,5),true)>0);Action a=NavalMilitaryAi.choose(s);assertFalse(a.x==5&&a.y==5);for(int y=0;y<12;y++)for(int x=0;x<12;x++)if(x!=5||y!=5)s.players.get(0).shots.add(new Shot(x,y,"miss"));a=NavalMilitaryAi.choose(s);assertEquals(5,a.x);assertEquals(5,a.y);
    }
    @Test void uncertainAirRiskIsChargedOnceAndDoesNotForceBattleships(){
        NavalState s=battle(List.of(ship("cruiser","e",9,9)),List.of(ship("carrier","c",0,0),ship("battleship","b",3,0)));Action a=NavalMilitaryAi.choose(s);assertEquals("fighter",a.weapon);var k=new NavalMilitaryAi.Knowledge(s.players.get(1),s.players.get(0));for(var option:NavalMilitaryAi.evaluate(s,k,false))assertEquals(option.gain()-option.cost(),option.score(),1e-9);
        double[] p=NavalMilitaryAi.inclusion(new double[]{.3,.35,.35},2);assertEquals(2,Arrays.stream(p).sum(),1e-9);assertEquals(.35+.3*.35/.7+.35*.35/.65,p[1],1e-9);
    }
    @Test void disabledCarrierNeedNotRevealItsAmbiguousFootprint(){NavalState s=battle(List.of(ship("torpedoCarrier","t",3,3)),List.of(ship("cruiser","c",0,0)));Player enemy=s.players.get(0),own=s.players.get(1);enemy.ships.get(0).hits.addAll(List.of("3,4","3,5"));enemy.shots.addAll(List.of(new Shot(3,4,"hit"),new Shot(3,5,"hit")));NavalMilitaryIntel intel=new NavalMilitaryIntel(own,enemy,s.events);assertTrue(intel.neutralized.contains("t"));assertTrue(intel.resolved.isEmpty());assertFalse(intel.torpedoThreat);enemy.ships.get(0).hits.clear();enemy.shots.clear();s.events.add(new Event(1,0,"torpedo",List.of(),"lost",0,0,null,List.of(),List.of(),List.of(),true,List.of(),"t",0));intel=new NavalMilitaryIntel(own,enemy,s.events);assertTrue(intel.neutralized.contains("t"));assertFalse(intel.torpedoThreat);assertTrue(intel.resolved.isEmpty());}
    @Test void publicGunHitsInferNeutralizedFootprintWithoutHiddenCoordinates(){
        Ship target=ship("battleship","b",2,2);target.hits.addAll(List.of("2,2","2,4"));NavalState s=battle(List.of(target),List.of(ship("cruiser","own",0,0)));Player enemy=s.players.get(0),own=s.players.get(1);enemy.shots.addAll(List.of(new Shot(2,2,"hit"),new Shot(2,4,"hit")));
        NavalMilitaryAi.Knowledge k=new NavalMilitaryAi.Knowledge(own,enemy);assertTrue(k.intel.neutralized.contains("b"));assertTrue(k.fresh(new Cell(2,3)));assertFalse(k.fresh(new Cell(3,5)));assertTrue(k.fresh(new Cell(4,5)));
        target.x=9;target.y=8;target.rotation=90;k=new NavalMilitaryAi.Knowledge(own,enemy);assertTrue(k.fresh(new Cell(2,3)));assertTrue(k.fresh(new Cell(9,8)));
        target.hits.remove("2,4");enemy.shots.remove(1);assertFalse(new NavalMilitaryAi.Knowledge(own,enemy).intel.neutralized.contains("b"));
    }
    @Test void interceptionCreatesAntiAirHuntAndSafeFlightEnablesAreaWeapon(){
        NavalState s=battle(List.of(ship("antiAir","aa",8,8),ship("cruiser","enemy",10,5)),List.of(ship("carrier","c",0,0),ship("cruiser","gun",3,0)));
        s.events.add(new Event(1,1,"fighter",List.of(),"intercept",2,5,null,List.of(),List.of(new Cell(0,5),new Cell(1,5),new Cell(2,5)),List.of(),true));
        NavalMilitaryIntel intel=new NavalMilitaryIntel(s.players.get(1),s.players.get(0),s.events);assertFalse(intel.aaHeads.isEmpty());Action a=NavalMilitaryAi.choose(s);if("shot".equals(a.weapon))assertTrue(intel.aaHeads.contains(new Cell(a.x,a.y)));else {List<Cell> path=new ArrayList<>();for(int x=0;x<=a.x+6;x++)path.add(new Cell(x,a.y));assertTrue(intel.flightRisk(path).exposure()<.25);}
        s.events.clear();List<Cell> route=new ArrayList<>();for(int x=0;x<=12;x++)route.add(new Cell(x,5));s.events.add(new Event(2,1,"fighter",List.of(),"safe",6,5,null,List.of(),route,List.of(),false));a=NavalMilitaryAi.choose(s);assertEquals("fighter",a.weapon);assertEquals(5,a.y);
    }
    @Test void mineThreatRequiresPublicEvidenceAndExpandedCapsRetainCoins(){
        NavalState s=battle(List.of(ship("cruiser","enemy",10,5)),List.of(ship("mineLayer","m",6,6),ship("cruiser","gun",3,0)));Player enemy=s.players.get(0),own=s.players.get(1);assertTrue(new NavalMilitaryIntel(own,enemy,s.events).torpedoThreat);enemy.ships.get(0).hits.add("10,6");enemy.shots.add(new Shot(10,6,"hit"));assertFalse(new NavalMilitaryIntel(own,enemy,s.events).torpedoThreat);assertNotEquals("mine",NavalMilitaryAi.choose(s).weapon);s.mineActions=1;assertEquals("mine",NavalMilitaryAi.choose(s).weapon);
        assertEquals(2,NavalMilitary.cap("carrier"));assertEquals(6,NavalMilitary.cap("radar"));assertEquals(4,NavalMilitary.cap("cruiser"));assertEquals(3,NavalMilitary.cap("decoy"));Set<Integer> coins=new HashSet<>();for(int i=0;i<25;i++){s.mode="AI";NavalMilitary.begin(s,0);Player ai=s.players.get(1);int cost=ai.ships.stream().mapToInt(t->NavalMilitary.MODELS.get(t.kind)[2]).sum();assertEquals(300-cost,ai.coins);coins.add(ai.coins);}assertTrue(coins.stream().anyMatch(c->c>0));
    }
    @Test void militaryRevisionHasTorpedoCarrierEightMinutesAndSequentialMines(){assertArrayEquals(new int[]{1,4,60,2},NavalMilitary.MODELS.get("torpedoCarrier"));Ship carrier=ship("torpedoCarrier","t",0,0);assertEquals("torpedo",NavalMilitary.parts(carrier).get(0).role());carrier.hits.add("0,2");assertFalse(NavalMilitary.parts(carrier).get(0).active());NavalState s=battle(List.of(ship("mineLayer","m",0,0),ship("cruiser","c",3,3)),List.of(ship("cruiser","e",9,9)));NavalEngine.attack(s,0,action("m","mine",5,5),0);assertEquals(0,s.turn);assertEquals(1,s.mineActions);assertThrows(RuntimeException.class,()->NavalEngine.attack(s,0,action("c","shot",9,9),0));NavalEngine.attack(s,0,action("m","mine",6,5),0);assertEquals(1,s.turn);assertEquals(0,s.mineActions);NavalMilitary.begin(s,1000);assertEquals(481000,s.deadline);}
    @Test void calibratedFirstShellUsesThirtyFiveAndFortyFivePercent(){for(int known:List.of(1,2)){int fresh=0;for(int i=0;i<500;i++){Ship gun=ship("battleship","a",0,0);gun.rotation=90;gun.w=3;gun.h=1;gun.hits.add("0,0");NavalState s=battle(List.of(gun),List.of(ship("cruiser","e",9,9)));s.players.get(1).shots.add(new Shot(3,5,"hit"));if(known==2)s.players.get(1).shots.add(new Shot(2,5,"hit"));NavalEngine.attack(s,0,action("a","shot",2,5),0);if(s.events.get(0).cells().get(0).x()==4)fresh++;}assertEquals(known==1?.35:.45,fresh/500.0,.08);}}
    @Test void pairsOfMinesAndCenterSubmarineDamage(){NavalState s=battle(List.of(ship("mineLayer","m",0,0),ship("cruiser","c",3,3)),List.of(ship("submarine","sub",5,5),ship("cruiser","e",9,9)));Action a=action("m","mine",5,0);a.targets=List.of(new Cell(5,0),new Cell(6,0));NavalEngine.attack(s,0,a,0);assertEquals(2,s.players.get(0).mines.size());assertEquals(2,s.players.get(0).ships.get(0).minesUsed);s.turn=0;NavalEngine.attack(s,0,action("c","shot",5,5),0);assertEquals(1,s.players.get(1).ships.get(0).hits.size());s.turn=0;NavalEngine.attack(s,0,action("c","shot",5,6),0);assertEquals(3,s.players.get(1).ships.get(0).hits.size());int n=s.players.get(1).shots.size();s.turn=0;NavalEngine.attack(s,0,action("c","shot",5,6),0);assertEquals("miss",s.events.get(s.events.size()-1).cells().get(0).result());assertEquals(n,s.players.get(1).shots.size());}
    @Test void aiFleetsAndKnowledgeAreVariedAndPublicOnly(){Set<String> fleets=new HashSet<>();Set<Integer> sizes=new HashSet<>();for(int i=0;i<50;i++){List<Ship> f=NavalMilitary.randomFleet();assertTrue(NavalMilitary.validate(f,true)<=300);fleets.add(f.stream().map(t->t.kind).sorted().toList().toString());sizes.add(f.size());}assertTrue(fleets.size()>10);assertTrue(sizes.size()>1);NavalState s=battle(List.of(ship("cruiser","hidden",8,8)),List.of(ship("cruiser","own",0,0)));Player enemy=s.players.get(0),own=s.players.get(1);enemy.shots.addAll(List.of(new Shot(5,5,"hit"),new Shot(6,5,"hit")));own.radar.add(new Radar(0,0,false));NavalMilitaryAi.Knowledge k=new NavalMilitaryAi.Knowledge(own,enemy);assertFalse(k.valid(new Cell(0,0)));assertTrue(k.fresh(new Cell(0,0)));assertTrue(k.score(new Cell(7,5))>k.score(new Cell(5,6)));}
    @Test void oldLostSubmarineGetsHitMarkersOnResume(){Ship sub=ship("submarine","s",0,0);sub.hits.addAll(List.of("0,0","0,1","0,2"));NavalState s=battle(List.of(sub,ship("cruiser","c",4,4)),List.of(ship("cruiser","e",9,9)));NavalEngine.normalize(s,0);assertEquals(3,s.players.get(0).shots.size());NavalEngine.normalize(s,0);assertEquals(3,s.players.get(0).shots.size());}
    @Test void fighterSamplesFourOrFiveOfSix(){for(int i=0;i<30;i++){NavalState s=battle(List.of(ship("carrier","a",0,0)),List.of(ship("cruiser","b",9,9)));NavalEngine.attack(s,0,action("a","fighter",2,5),0);List<Shot> cells=s.events.get(0).cells();assertTrue(List.of(4,5).contains(cells.size()));assertEquals(cells.size(),new HashSet<>(cells).size());assertTrue(cells.stream().allMatch(c->c.x()>=2&&c.x()<8&&c.y()==5));}}
    Ship ship(String kind,String id,int x,int y) { int[] m=NavalMilitary.MODELS.get(kind);Ship s=new Ship(id,x,y,m[0],m[1]);s.kind=kind;return s; }
    NavalState battle(List<Ship> a,List<Ship> b) { NavalState s=new NavalState();s.ruleSet="MILITARY";s.phase="BATTLE";s.mode="MULTIPLAYER";Player p=NavalEngine.player("a","A"),q=NavalEngine.player("b","B");p.ships=new ArrayList<>(a);q.ships=new ArrayList<>(b);s.players.add(p);s.players.add(q);return s; }
    Action action(String id,String weapon,int x,int y) {Action a=new Action();a.shipId=id;a.weapon=weapon;a.x=x;a.y=y;return a;}
    @Test void randomFleetAndOpening() {for(int i=0;i<20;i++)assertTrue(NavalMilitary.validate(NavalMilitary.randomFleet(),true)<=300);NavalState s=battle(List.of(),List.of());s.mode="AI";NavalEngine.beginPlacement(s,0);assertTrue(s.players.get(0).ships.isEmpty());assertEquals(300,s.players.get(0).coins);assertTrue(s.players.get(1).ready);}
    @Test void gunDamageEndsBattleWithoutSinking() {NavalState s=battle(List.of(ship("cruiser","a",0,0)),List.of(ship("cruiser","b",5,5),ship("radar","r",8,8),ship("decoy","d",10,0)));NavalEngine.attack(s,0,action("a","shot",5,5),0);assertEquals("FINISHED",s.phase);assertEquals(0,s.winner);assertFalse(NavalEngine.sunk(s.players.get(1).ships.get(0)));}
    @Test void planesAreInterceptedAndUnavailable() {NavalState s=battle(List.of(ship("carrier","a",0,0)),List.of(ship("antiAir","aa",3,1),ship("cruiser","c",8,5)));NavalEngine.attack(s,0,action("a","fighter",3,2),0);assertTrue(s.events.get(0).destroyed());assertTrue(s.events.get(0).cells().isEmpty());assertEquals(List.of(0),s.players.get(0).ships.get(0).lostPlanes);assertEquals(1,s.turn);s.turn=0;assertThrows(RuntimeException.class,()->NavalEngine.attack(s,0,action("a","fighter",3,2),0));}
    @Test void torpedoTurnsOutsideBoard() {NavalState s=battle(List.of(ship("torpedo","a",0,0)),List.of(ship("carrier","b",8,3)));NavalEngine.attack(s,0,action("a","torpedo",11,2),0);assertEquals(new Cell(12,2),s.events.get(0).route().get(12));assertEquals(1,s.events.get(0).cells().size());assertTrue(s.players.get(0).ships.get(0).lostPlanes.isEmpty());}
    @Test void forgedTorpedoIndexCannotBypassAircraftLoss() {NavalState s=battle(List.of(ship("torpedo","a",0,0)),List.of(ship("carrier","b",8,3)));Action forged=action("a","torpedo",2,3);forged.plane=1;assertThrows(RuntimeException.class,()->NavalEngine.attack(s,0,forged,0));assertTrue(s.events.isEmpty());}
    @Test void radarSeesDecoyAndNoExtraTurnOnHit() {NavalState s=battle(List.of(ship("radar","a",0,0),ship("cruiser","c",5,5)),List.of(ship("decoy","d",3,3),ship("cruiser","c2",8,5)));NavalEngine.attack(s,0,action("a","radar",3,3),0);assertEquals(2,s.players.get(0).radar.stream().filter(Radar::occupied).count());assertEquals(1,s.turn);assertTrue(s.players.get(1).shots.isEmpty());}
    @Test void serverRejectsSpoofedGeometryBudgetAndReady() {Ship s=ship("carrier","a",0,0);s.w=2;assertThrows(RuntimeException.class,()->NavalMilitary.validate(List.of(s),true));assertThrows(RuntimeException.class,()->NavalMilitary.validate(List.of(ship("radar","a",0,0)),true));assertThrows(RuntimeException.class,()->NavalMilitary.validate(List.of(ship("carrier","a",0,0),ship("carrier","b",4,0),ship("carrier","c",8,0)),true));}
    @Test void rotatingBowAndAaDamage() {Ship s=ship("battleship","a",2,3);s.rotation=90;s.w=3;s.h=1;assertEquals(new Cell(4,3),NavalMilitary.parts(s).get(0).cell());s.hits.add("4,3");assertFalse(NavalMilitary.parts(s).get(0).active());Player p=new Player();Ship aa=ship("antiAir","aa",2,2);p.ships.add(aa);assertEquals(12,NavalMilitary.coverage(p).size());aa.hits.add("2,2");assertTrue(NavalMilitary.coverage(p).isEmpty());}
    @Test void opponentDeploymentRemainsPrivate() {NavalState s=battle(List.of(ship("carrier","a",0,0)),List.of(ship("cruiser","b",8,3)));var v=NavalEngine.view(s,0,0);assertEquals("MILITARY",v.get("ruleSet"));var players=(List<?>)v.get("players");assertTrue(((List<?>)((Map<?,?>)players.get(1)).get("ships")).isEmpty());}
    @Test void bomberAndSharedCaps(){NavalState s=battle(List.of(ship("bomberCarrier","a",0,0)),List.of(ship("cruiser","b",9,9)));NavalEngine.attack(s,0,action("a","bomber",3,5),0);assertTrue(List.of(5,6).contains(s.events.get(0).cells().size()));assertEquals(new Cell(0,5),s.events.get(0).route().get(0));assertEquals(100,NavalMilitary.validate(List.of(ship("carrier","a",0,0),ship("bomberCarrier","b",4,0)),true));}
    @Test void mineLayerHasTenActionsAndSurvivesOneHit(){Ship m=ship("mineLayer","m",0,0);m.hits.add("0,0");NavalState s=battle(List.of(m,ship("cruiser","c",3,3)),List.of(ship("cruiser","b",9,9)));for(int i=0;i<10;i++){s.turn=0;NavalEngine.attack(s,0,action("m","mine",2+i,0),0);assertEquals(i%2==0?0:1,s.turn);}assertEquals(10,s.players.get(0).mines.size());s.turn=0;assertThrows(RuntimeException.class,()->NavalEngine.attack(s,0,action("m","mine",5,1),0));}
    @Test void jammerRectangleAndSubmarineMineLoss(){Ship j=ship("jammer","j",8,6);j.rotation=270;j.w=2;j.h=1;Player p=new Player();p.ships.add(j);assertEquals(12,NavalMilitary.jamming(p).size());assertTrue(NavalMilitary.jamming(p).contains(new Cell(4,5)));j.hits.add("8,6");assertTrue(NavalMilitary.jamming(p).isEmpty());NavalState s=battle(List.of(ship("submarine","a",0,0),ship("cruiser","c",5,5)),List.of(ship("cruiser","b",9,9)));s.players.get(1).mines.add(new Cell(0,5));NavalEngine.attack(s,0,action("a","submarine",4,5),0);assertTrue(s.events.get(0).destroyed());assertEquals(1,s.events.get(0).cells().size());assertEquals(3,s.players.get(0).ships.get(0).hits.size());assertEquals(3,s.players.get(0).shots.size());assertEquals(3,s.events.get(0).backfire().size());}
    @Test void bothRulesTorpedoesStopAtDestroyedHull(){for(String rules:List.of("CLASSIC","MILITARY")){Ship wreck=ship("cruiser","w",3,4);wreck.hits.add("3,4");NavalState s=battle(List.of(ship("torpedo","a",0,0)),List.of(wreck,ship("cruiser","b",7,4),ship("cruiser","c",10,8)));s.ruleSet=rules;s.players.get(0).inventory.put("torpedo",1);s.players.get(1).shots.add(new Shot(3,4,"hit"));NavalEngine.attack(s,0,action("a","torpedo",1,4),0);Event e=s.events.get(0);assertEquals(3,e.cells().get(e.cells().size()-1).x());assertTrue(s.players.get(1).ships.get(1).hits.isEmpty());assertEquals(1,wreck.hits.size());assertTrue(e.backfire().isEmpty());}}
    @Test void auxiliaryFleetCannotPreventDefeat(){Ship c=ship("carrier","c",0,0);c.lostPlanes.addAll(List.of(0,1));NavalState s=battle(List.of(c,ship("radar","r",2,6),ship("mineLayer","m",4,6),ship("antiAir","a",6,6),ship("decoy","d",8,6)),List.of(ship("cruiser","e",8,8)));assertTrue(NavalMilitary.checkDefeat(s,0));assertEquals(1,s.winner);assertEquals("FINISHED",s.phase);}
}
